diff --git a/mailnews/base/test/unit/test_folderNames.js b/mailnews/base/test/unit/test_folderNames.js
new file mode 100644
index 00000000000..c35f20386a0
--- /dev/null
+++ b/mailnews/base/test/unit/test_folderNames.js
@@ -0,0 +1,159 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+/**
+ * Tests folders which should have a localised name that is different from the
+ * folder's name.
+ */
+
+add_task(function () {
+  // Get the localized strings. This test should work in any locale, or if you
+  // change the string values in messenger.properties.
+
+  const bundle = Services.strings.createBundle(
+    "chrome://messenger/locale/messenger.properties"
+  );
+  const inboxFolderName = bundle.GetStringFromName("inboxFolderName");
+  const trashFolderName = bundle.GetStringFromName("trashFolderName");
+  const sentFolderName = bundle.GetStringFromName("sentFolderName");
+  const draftsFolderName = bundle.GetStringFromName("draftsFolderName");
+  const templatesFolderName = bundle.GetStringFromName("templatesFolderName");
+  const outboxFolderName = bundle.GetStringFromName("outboxFolderName");
+  const junkFolderName = bundle.GetStringFromName("junkFolderName");
+  const archivesFolderName = bundle.GetStringFromName("archivesFolderName");
+
+  Cc["@mozilla.org/msgFolder/msgFolderService;1"]
+    .getService(Ci.nsIMsgFolderService)
+    .initializeFolderStrings();
+
+  const panorama = Services.prefs.getBoolPref("mail.panorama.enabled", false);
+  const account = MailServices.accounts.createLocalMailAccount();
+
+  const rootFolder = account.incomingServer.rootFolder;
+  rootFolder.QueryInterface(Ci.nsIMsgLocalMailFolder);
+  Assert.equal(rootFolder.name, "Local Folders");
+  Assert.equal(rootFolder.localizedName, "Local Folders");
+
+  const inboxFolder = rootFolder.createLocalSubfolder("Inbox");
+  inboxFolder.setFlag(Ci.nsMsgFolderFlags.Inbox);
+  Assert.equal(inboxFolder.name, "Inbox");
+  Assert.equal(inboxFolder.localizedName, inboxFolderName);
+  Assert.equal(
+    inboxFolder.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Inbox" : ""
+  );
+
+  // Normal sent mail folder as created by us.
+  const sentFolder1 = rootFolder.createLocalSubfolder("Sent");
+  sentFolder1.setFlag(Ci.nsMsgFolderFlags.SentMail);
+  Assert.equal(sentFolder1.name, "Sent");
+  Assert.equal(sentFolder1.localizedName, sentFolderName);
+  Assert.equal(
+    sentFolder1.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Sent" : ""
+  );
+
+  // Gmail.
+  const sentFolder2 = rootFolder.createLocalSubfolder("Sent Mail");
+  sentFolder2.setFlag(Ci.nsMsgFolderFlags.SentMail);
+  Assert.equal(sentFolder2.name, "Sent Mail");
+  Assert.equal(sentFolder2.localizedName, "Sent");
+
+  const sentFolder3 = rootFolder.createLocalSubfolder("Outbox");
+  sentFolder3.setFlag(Ci.nsMsgFolderFlags.SentMail);
+  Assert.equal(sentFolder3.name, "Outbox");
+  Assert.equal(sentFolder3.localizedName, "Sent");
+
+  // Normal drafts folder as created by us, but with weird capitalisation to
+  // prove it works. The case is "corrected" by nsMsgDBFolder::AddSubfolder.
+  const draftsFolder1 = rootFolder.createLocalSubfolder("drAfTs");
+  draftsFolder1.setFlag(Ci.nsMsgFolderFlags.Drafts);
+  Assert.equal(draftsFolder1.name, "Drafts");
+  Assert.equal(draftsFolder1.localizedName, draftsFolderName);
+  Assert.equal(
+    draftsFolder1.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Drafts" : ""
+  );
+
+  // Yahoo!.
+  const draftsFolder2 = rootFolder.createLocalSubfolder("Draft");
+  draftsFolder2.setFlag(Ci.nsMsgFolderFlags.Drafts);
+  Assert.equal(draftsFolder2.name, "Draft");
+  Assert.equal(draftsFolder2.localizedName, "Drafts");
+  Assert.equal(
+    draftsFolder2.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Draft" : ""
+  );
+
+  const templatesFolder = rootFolder.createLocalSubfolder("Templates");
+  templatesFolder.setFlag(Ci.nsMsgFolderFlags.Templates);
+  Assert.equal(templatesFolder.name, "Templates");
+  Assert.equal(templatesFolder.localizedName, templatesFolderName);
+  Assert.equal(
+    templatesFolder.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Templates" : ""
+  );
+
+  const trashFolder1 = rootFolder.getChildNamed("Trash");
+  Assert.equal(trashFolder1.name, "Trash");
+  Assert.equal(trashFolder1.localizedName, trashFolderName);
+  Assert.equal(
+    trashFolder1.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Trash" : ""
+  );
+
+  const trashFolder2 = rootFolder.createLocalSubfolder("Bin");
+  trashFolder2.setFlag(Ci.nsMsgFolderFlags.Trash);
+  Assert.equal(trashFolder2.name, "Bin");
+  Assert.equal(trashFolder2.localizedName, trashFolderName);
+  Assert.equal(
+    trashFolder2.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Bin" : ""
+  );
+
+  const trashFolder3 = rootFolder.createLocalSubfolder("Deleted");
+  trashFolder3.setFlag(Ci.nsMsgFolderFlags.Trash);
+  Assert.equal(trashFolder3.name, "Deleted");
+  Assert.equal(trashFolder3.localizedName, "Trash");
+  Assert.equal(
+    trashFolder3.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Deleted" : ""
+  );
+
+  const outboxFolder = rootFolder.getChildNamed("Unsent Messages");
+  outboxFolder.setFlag(Ci.nsMsgFolderFlags.Queue);
+  Assert.equal(outboxFolder.name, "Unsent Messages");
+  Assert.equal(outboxFolder.localizedName, outboxFolderName);
+  Assert.equal(
+    outboxFolder.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Unsent Messages" : ""
+  );
+
+  const junkFolder = rootFolder.createLocalSubfolder("Junk");
+  junkFolder.setFlag(Ci.nsMsgFolderFlags.Junk);
+  Assert.equal(junkFolder.name, "Junk");
+  Assert.equal(junkFolder.localizedName, junkFolderName);
+  Assert.equal(
+    junkFolder.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Junk" : ""
+  );
+
+  const archivesFolder1 = rootFolder.createLocalSubfolder("Archives");
+  archivesFolder1.setFlag(Ci.nsMsgFolderFlags.Archive);
+  Assert.equal(archivesFolder1.name, "Archives");
+  Assert.equal(archivesFolder1.localizedName, archivesFolderName);
+  Assert.equal(
+    archivesFolder1.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Archives" : ""
+  );
+
+  const archivesFolder2 = rootFolder.createLocalSubfolder("Archive");
+  archivesFolder2.setFlag(Ci.nsMsgFolderFlags.Archive);
+  Assert.equal(archivesFolder2.name, "Archive");
+  Assert.equal(archivesFolder2.localizedName, archivesFolderName);
+  Assert.equal(
+    archivesFolder2.msgDatabase.dBFolderInfo.folderName,
+    panorama ? "Archive" : ""
+  );
+});
diff --git a/mailnews/base/test/unit/test_folderNamesExisting.js b/mailnews/base/test/unit/test_folderNamesExisting.js
new file mode 100644
index 00000000000..cf9213ddcf6
--- /dev/null
+++ b/mailnews/base/test/unit/test_folderNamesExisting.js
@@ -0,0 +1,158 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+/**
+ * Tests folders which should have a localised name that is different from the
+ * folder's name, even if there is a name stored in the folder cache or
+ * summary file from an earlier version.
+ */
+
+add_task(async function () {
+  // Set up a profile with an account.
+
+  const profileDir = do_get_profile();
+  Services.prefs.setStringPref("mail.account.account1.identities", "id1");
+  Services.prefs.setStringPref("mail.account.account1.server", "server1");
+  Services.prefs.setStringPref("mail.accountmanager.accounts", "account1");
+  Services.prefs.setStringPref("mail.identity.id1.fullName", "Test User");
+  Services.prefs.setStringPref("mail.identity.id1.useremail", "test@localhost");
+  Services.prefs.setStringPref(
+    "mail.server.server1.directory-rel",
+    "[ProfD]Mail/Local Folders"
+  );
+  Services.prefs.setStringPref("mail.server.server1.hostname", "Local Folders");
+  Services.prefs.setStringPref("mail.server.server1.type", "none");
+  Services.prefs.setStringPref("mail.server.server1.userName", "nobody");
+
+  // Create the mail files.
+
+  const localFoldersPath = PathUtils.join(
+    profileDir.path,
+    "Mail",
+    "Local Folders"
+  );
+  await IOUtils.makeDirectory(localFoldersPath);
+
+  const inboxSummaryFile = do_get_file("data/frenchInbox.msf");
+  const inboxSummaryPath = PathUtils.join(localFoldersPath, "Inbox.msf");
+  await IOUtils.copy(inboxSummaryFile.path, inboxSummaryPath);
+  await IOUtils.writeUTF8(
+    PathUtils.join(profileDir.path, "Mail", "Local Folders", "Inbox"),
+    ""
+  );
+
+  const draftsSummaryFile = do_get_file("data/frenchDrafts.msf");
+  const draftsSummaryPath = PathUtils.join(localFoldersPath, "Drafts.msf");
+  await IOUtils.copy(draftsSummaryFile.path, draftsSummaryPath);
+  await IOUtils.writeUTF8(
+    PathUtils.join(profileDir.path, "Mail", "Local Folders", "Drafts"),
+    ""
+  );
+
+  // Add the Inbox folder to the folder cache, to check what happens if the
+  // name is in the folder cache. Don't add the Drafts folder, to check what
+  // happens if the name isn't in the folder cache.
+
+  const folderCachePath = PathUtils.join(profileDir.path, "folderCache.json");
+  await IOUtils.writeJSON(folderCachePath, {
+    [inboxSummaryPath]: { flags: 0x1004, folderName: "Courrier entrant" },
+  });
+
+  // Get the localized strings. This test should work in any locale.
+  // (Except French, because the names are already in French.)
+
+  const bundle = Services.strings.createBundle(
+    "chrome://messenger/locale/messenger.properties"
+  );
+  const inboxFolderName = bundle.GetStringFromName("inboxFolderName");
+  const draftsFolderName = bundle.GetStringFromName("draftsFolderName");
+
+  // Start the account manager.
+
+  Cc["@mozilla.org/msgFolder/msgFolderService;1"]
+    .getService(Ci.nsIMsgFolderService)
+    .initializeFolderStrings();
+
+  MailServices.accounts.accounts;
+  const server = MailServices.accounts.localFoldersServer;
+  Assert.equal(
+    server.localPath.path,
+    localFoldersPath,
+    "sanity check - we installed the files in the right place"
+  );
+  const rootFolder = server.rootFolder;
+
+  // Check the Inbox folder is correctly localized.
+
+  const inboxFolder = rootFolder.getChildNamed("Inbox");
+  Assert.equal(
+    inboxFolder.summaryFile.path,
+    inboxSummaryPath,
+    "sanity check - we're using the installed summary file"
+  );
+  Assert.equal(
+    inboxFolder.flags,
+    Ci.nsMsgFolderFlags.Inbox | Ci.nsMsgFolderFlags.Mail,
+    "flags should be loaded from the folder cache"
+  );
+  Assert.equal(
+    inboxFolder.name,
+    "Inbox",
+    "inbox folder's name should be from the file name"
+  );
+  Assert.equal(
+    inboxFolder.localizedName,
+    inboxFolderName,
+    "inbox folder's localized name should be localized"
+  );
+  Assert.notEqual(
+    inboxFolder.msgDatabase.dBFolderInfo.folderName,
+    inboxFolderName,
+    "inbox folder name should not have been updated in the summary file"
+  );
+
+  // Check the Drafts folder is correctly localized.
+
+  const draftsFolder = rootFolder.getChildNamed("Drafts");
+  Assert.equal(
+    draftsFolder.summaryFile.path,
+    draftsSummaryPath,
+    "sanity check - we're using the installed summary file"
+  );
+  Assert.equal(
+    draftsFolder.flags,
+    Ci.nsMsgFolderFlags.Drafts | Ci.nsMsgFolderFlags.Mail,
+    "flags should be loaded from the summary file"
+  );
+  Assert.equal(
+    draftsFolder.name,
+    "Drafts",
+    "drafts folder's name should be from the file name"
+  );
+  Assert.equal(
+    draftsFolder.localizedName,
+    draftsFolderName,
+    "drafts folder's localized name should be localized"
+  );
+  Assert.notEqual(
+    draftsFolder.msgDatabase.dBFolderInfo.folderName,
+    draftsFolderName,
+    "drafts folder name should not have been updated in the summary file"
+  );
+
+  // Check that the localised name was not written to the folder cache.
+
+  MailServices.accounts.folderCache.flush();
+  const folderCache = await IOUtils.readJSON(folderCachePath);
+  Assert.notEqual(
+    folderCache[inboxSummaryPath].folderName,
+    inboxFolderName,
+    "inbox folder name should not have been updated in the folder cache"
+  );
+  Assert.notEqual(
+    folderCache[draftsSummaryPath]?.folderName,
+    draftsFolderName,
+    "drafts folder name should not have been updated in the folder cache"
+  );
+});
